CREATE TABLE projects(id INTEGER PRIMARY KEY,name TEXT NOT NULL,root_path TEXT NOT NULL UNIQUE,repository_url TEXT,created_at INTEGER NOT NULL,last_seen_at INTEGER NOT NULL,summary TEXT NOT NULL DEFAULT '',environment_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE sessions(id INTEGER PRIMARY KEY,started_at INTEGER NOT NULL,ended_at INTEGER,end_reason TEXT,project_id INTEGER REFERENCES projects(id),summary TEXT NOT NULL DEFAULT '',reflection TEXT NOT NULL DEFAULT '',status TEXT NOT NULL CHECK(status IN ('active','completed','aborted','needs_consolidation')));
CREATE TABLE tasks(id INTEGER PRIMARY KEY,session_id INTEGER REFERENCES sessions(id),project_id INTEGER REFERENCES projects(id),title TEXT NOT NULL,objective TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'planned' CHECK(status IN ('planned','active','blocked','verifying','completed','abandoned')),risk TEXT NOT NULL DEFAULT 'low',domain TEXT NOT NULL DEFAULT 'general',created_at INTEGER NOT NULL,completed_at INTEGER);
CREATE TABLE events(id INTEGER PRIMARY KEY,ts INTEGER NOT NULL,session_id INTEGER REFERENCES sessions(id),task_id INTEGER REFERENCES tasks(id),type TEXT NOT NULL,payload_json TEXT NOT NULL CHECK(json_valid(payload_json)));
CREATE INDEX events_session ON events(session_id,id);
CREATE INDEX events_type ON events(type,ts);
CREATE TRIGGER events_no_update BEFORE UPDATE ON events BEGIN SELECT RAISE(ABORT,'events are append-only'); END;
CREATE TRIGGER events_no_delete BEFORE DELETE ON events BEGIN SELECT RAISE(ABORT,'events are append-only'); END;
CREATE TABLE messages(id INTEGER PRIMARY KEY,session_id INTEGER NOT NULL REFERENCES sessions(id),ts INTEGER NOT NULL,role TEXT NOT NULL CHECK(role IN ('user','assistant','tool','system_internal')),content_json TEXT NOT NULL CHECK(json_valid(content_json)),tool_call_id TEXT,token_count INTEGER);
CREATE INDEX messages_session ON messages(session_id,id);
CREATE TABLE journal_entries(id INTEGER PRIMARY KEY,session_id INTEGER NOT NULL UNIQUE REFERENCES sessions(id),started_at INTEGER NOT NULL,ended_at INTEGER NOT NULL,narrative TEXT NOT NULL,summary TEXT NOT NULL,outcome TEXT NOT NULL,salience REAL NOT NULL DEFAULT 0.5,created_at INTEGER NOT NULL);
CREATE TABLE episodes(id INTEGER PRIMARY KEY,session_id INTEGER REFERENCES sessions(id),project_id INTEGER REFERENCES projects(id),started_at INTEGER NOT NULL,ended_at INTEGER,type TEXT NOT NULL,title TEXT NOT NULL,summary TEXT NOT NULL,content TEXT NOT NULL,outcome TEXT NOT NULL,salience REAL NOT NULL DEFAULT 0.5,confidence REAL NOT NULL DEFAULT 0.5,accessibility REAL NOT NULL DEFAULT 1,recall_count INTEGER NOT NULL DEFAULT 0,last_recalled_at INTEGER,created_at INTEGER NOT NULL);
CREATE TABLE entities(id INTEGER PRIMARY KEY,canonical_name TEXT NOT NULL,type TEXT NOT NULL,aliases_json TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(aliases_json)),UNIQUE(canonical_name,type));
CREATE TABLE episode_entities(episode_id INTEGER NOT NULL REFERENCES episodes(id),entity_id INTEGER NOT NULL REFERENCES entities(id),PRIMARY KEY(episode_id,entity_id));
CREATE TABLE facts(id INTEGER PRIMARY KEY,project_id INTEGER REFERENCES projects(id),subject TEXT NOT NULL,predicate TEXT NOT NULL,object TEXT NOT NULL,confidence REAL NOT NULL DEFAULT 0.5,source_episode_id INTEGER REFERENCES episodes(id),valid_from INTEGER NOT NULL,valid_to INTEGER,superseded_by INTEGER REFERENCES facts(id),created_at INTEGER NOT NULL,last_confirmed_at INTEGER);
CREATE INDEX facts_current ON facts(subject,predicate,valid_to);
CREATE TABLE fact_entities(fact_id INTEGER REFERENCES facts(id),entity_id INTEGER REFERENCES entities(id),PRIMARY KEY(fact_id,entity_id));
CREATE TABLE beliefs(id INTEGER PRIMARY KEY,statement TEXT NOT NULL,domain TEXT NOT NULL DEFAULT 'general',prior REAL NOT NULL DEFAULT 0.5,reasoning_confidence REAL NOT NULL DEFAULT 0.5,evidence_confidence REAL NOT NULL DEFAULT 0.5,operational_confidence REAL NOT NULL DEFAULT 0.5,status TEXT NOT NULL DEFAULT 'unresolved',source_event_id INTEGER REFERENCES events(id),created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE hypotheses(id INTEGER PRIMARY KEY,task_id INTEGER REFERENCES tasks(id),statement TEXT NOT NULL,confidence REAL NOT NULL DEFAULT 0.5,status TEXT NOT NULL DEFAULT 'unresolved' CHECK(status IN ('unresolved','confirmed','rejected','superseded')),source_event_id INTEGER REFERENCES events(id),created_at INTEGER NOT NULL);
CREATE TABLE corrections(id INTEGER PRIMARY KEY,fact_id INTEGER REFERENCES facts(id),corrected_fact_id INTEGER REFERENCES facts(id),description TEXT NOT NULL,source_event_id INTEGER NOT NULL REFERENCES events(id),created_at INTEGER NOT NULL);
CREATE TABLE artifacts(id INTEGER PRIMARY KEY,project_id INTEGER REFERENCES projects(id),type TEXT NOT NULL,path TEXT NOT NULL,description TEXT NOT NULL,created_session_id INTEGER REFERENCES sessions(id),last_modified_session_id INTEGER REFERENCES sessions(id),created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(project_id,path));
CREATE TABLE artifact_versions(id INTEGER PRIMARY KEY,artifact_id INTEGER NOT NULL REFERENCES artifacts(id),session_id INTEGER REFERENCES sessions(id),hash TEXT NOT NULL,summary TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE artifact_entities(artifact_id INTEGER REFERENCES artifacts(id),entity_id INTEGER REFERENCES entities(id),PRIMARY KEY(artifact_id,entity_id));
CREATE TABLE assumptions(id INTEGER PRIMARY KEY,task_id INTEGER REFERENCES tasks(id),statement TEXT NOT NULL,confidence REAL NOT NULL DEFAULT 0.5,impact_if_wrong TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'unresolved',verification_method TEXT NOT NULL,source_event_id INTEGER REFERENCES events(id),created_at INTEGER NOT NULL);
CREATE TABLE predictions(id INTEGER PRIMARY KEY,task_id INTEGER REFERENCES tasks(id),statement TEXT NOT NULL,expected_outcome TEXT NOT NULL,confidence REAL NOT NULL,domain TEXT NOT NULL DEFAULT 'general',source_event_id INTEGER REFERENCES events(id),created_at INTEGER NOT NULL);
CREATE TABLE observations(id INTEGER PRIMARY KEY,task_id INTEGER REFERENCES tasks(id),prediction_id INTEGER REFERENCES predictions(id),statement TEXT NOT NULL,matched INTEGER,source_event_id INTEGER NOT NULL REFERENCES events(id),created_at INTEGER NOT NULL);
CREATE UNIQUE INDEX one_prediction_outcome ON observations(prediction_id) WHERE prediction_id IS NOT NULL;
CREATE TABLE evidence(id INTEGER PRIMARY KEY,target_type TEXT NOT NULL,target_id INTEGER NOT NULL,kind TEXT NOT NULL,direction TEXT NOT NULL CHECK(direction IN ('support','against')),weight REAL NOT NULL,reliability REAL NOT NULL,source_event_id INTEGER NOT NULL REFERENCES events(id),created_at INTEGER NOT NULL,UNIQUE(target_type,target_id,kind,direction,source_event_id));
CREATE TABLE fact_evidence(id INTEGER PRIMARY KEY,fact_id INTEGER NOT NULL REFERENCES facts(id),evidence_id INTEGER NOT NULL REFERENCES evidence(id),UNIQUE(fact_id,evidence_id));
CREATE TABLE task_checks(id INTEGER PRIMARY KEY,task_id INTEGER NOT NULL REFERENCES tasks(id),description TEXT NOT NULL,required INTEGER NOT NULL DEFAULT 1,status TEXT NOT NULL DEFAULT 'unresolved' CHECK(status IN ('unresolved','passed','failed','waived')),evidence_id INTEGER REFERENCES evidence(id));
CREATE TABLE goals(id INTEGER PRIMARY KEY,scope TEXT NOT NULL,project_id INTEGER REFERENCES projects(id),description TEXT NOT NULL,priority REAL NOT NULL DEFAULT 0.5,status TEXT NOT NULL DEFAULT 'active',created_at INTEGER NOT NULL,completed_at INTEGER);
CREATE TABLE intentions(id INTEGER PRIMARY KEY,trigger_type TEXT NOT NULL,trigger_json TEXT NOT NULL CHECK(json_valid(trigger_json)),action_or_reminder TEXT NOT NULL,reason TEXT NOT NULL,priority REAL NOT NULL DEFAULT 0.5,status TEXT NOT NULL DEFAULT 'active',created_at INTEGER NOT NULL,expires_at INTEGER);
CREATE TABLE commitments(id INTEGER PRIMARY KEY,description TEXT NOT NULL,origin_event INTEGER NOT NULL REFERENCES events(id),due_condition TEXT NOT NULL,priority REAL NOT NULL DEFAULT 0.7,status TEXT NOT NULL DEFAULT 'active',created_at INTEGER NOT NULL,completed_at INTEGER);
CREATE TABLE open_loops(id INTEGER PRIMARY KEY,kind TEXT NOT NULL,description TEXT NOT NULL,project_id INTEGER REFERENCES projects(id),priority REAL NOT NULL DEFAULT 0.5,trigger_json TEXT NOT NULL DEFAULT '{}',state TEXT NOT NULL DEFAULT 'open',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE curiosities(id INTEGER PRIMARY KEY,question TEXT NOT NULL,project_id INTEGER REFERENCES projects(id),priority REAL NOT NULL DEFAULT 0.2,status TEXT NOT NULL DEFAULT 'open',created_at INTEGER NOT NULL);
CREATE TABLE praxis(id INTEGER PRIMARY KEY,name TEXT NOT NULL,scope TEXT NOT NULL,project_id INTEGER REFERENCES projects(id),domain TEXT NOT NULL DEFAULT 'general',trigger TEXT NOT NULL,procedure TEXT NOT NULL,rationale TEXT NOT NULL,limitations TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'candidate' CHECK(status IN ('candidate','learned','validated','habitual','deprecated')),alpha REAL NOT NULL DEFAULT 1,beta REAL NOT NULL DEFAULT 1,uses INTEGER NOT NULL DEFAULT 0,successes INTEGER NOT NULL DEFAULT 0,failures INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,last_used_at INTEGER);
CREATE TABLE praxis_evidence(id INTEGER PRIMARY KEY,praxis_id INTEGER NOT NULL REFERENCES praxis(id),session_id INTEGER REFERENCES sessions(id),task_id INTEGER REFERENCES tasks(id),outcome TEXT NOT NULL,duration INTEGER NOT NULL DEFAULT 0,tool_calls INTEGER NOT NULL DEFAULT 0,notes TEXT NOT NULL,source_event_id INTEGER NOT NULL REFERENCES events(id),created_at INTEGER NOT NULL,UNIQUE(praxis_id,task_id));
CREATE TABLE failed_strategies(id INTEGER PRIMARY KEY,task_id INTEGER REFERENCES tasks(id),context TEXT NOT NULL,strategy TEXT NOT NULL,failure TEXT NOT NULL,lesson TEXT NOT NULL,source_event_id INTEGER NOT NULL REFERENCES events(id),created_at INTEGER NOT NULL);
CREATE TABLE skills(id INTEGER PRIMARY KEY,praxis_id INTEGER NOT NULL REFERENCES praxis(id),name TEXT NOT NULL,workflow_json TEXT NOT NULL CHECK(json_valid(workflow_json)),source_event_id INTEGER NOT NULL REFERENCES events(id),created_at INTEGER NOT NULL);
CREATE TABLE self_beliefs(id INTEGER PRIMARY KEY,dimension TEXT NOT NULL UNIQUE,belief TEXT NOT NULL,confidence REAL NOT NULL DEFAULT 0.5,evidence_count INTEGER NOT NULL DEFAULT 0,source_event_id INTEGER REFERENCES events(id),created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE developed_traits(id INTEGER PRIMARY KEY,trait TEXT NOT NULL,confidence REAL NOT NULL,evidence_count INTEGER NOT NULL,source_event_id INTEGER NOT NULL REFERENCES events(id),created_at INTEGER NOT NULL);
CREATE TABLE relationship_beliefs(id INTEGER PRIMARY KEY,belief TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('explicit','inferred')),confidence REAL NOT NULL,evidence_count INTEGER NOT NULL,source_event_id INTEGER NOT NULL REFERENCES events(id),created_at INTEGER NOT NULL);
CREATE TABLE tool_runs(id INTEGER PRIMARY KEY,session_id INTEGER REFERENCES sessions(id),task_id INTEGER REFERENCES tasks(id),tool TEXT NOT NULL,arguments_json TEXT NOT NULL CHECK(json_valid(arguments_json)),started_at INTEGER NOT NULL,duration_ms INTEGER,status TEXT NOT NULL,exit_code INTEGER,stdout_size INTEGER NOT NULL DEFAULT 0,stderr_size INTEGER NOT NULL DEFAULT 0,error_type TEXT,result_hash TEXT);
CREATE TABLE model_calls(id INTEGER PRIMARY KEY,session_id INTEGER REFERENCES sessions(id),task_id INTEGER REFERENCES tasks(id),purpose TEXT NOT NULL,model TEXT NOT NULL,started_at INTEGER NOT NULL,duration_ms INTEGER,status TEXT NOT NULL,input_tokens INTEGER,output_tokens INTEGER,approximate INTEGER NOT NULL DEFAULT 1,error TEXT);
CREATE TABLE continuity_state(id INTEGER PRIMARY KEY CHECK(id=1),last_session_id INTEGER REFERENCES sessions(id),active_project_id INTEGER REFERENCES projects(id),recent_topics TEXT NOT NULL DEFAULT '[]',recent_entities TEXT NOT NULL DEFAULT '[]',unfinished_task_ids TEXT NOT NULL DEFAULT '[]',important_open_loop_ids TEXT NOT NULL DEFAULT '[]',last_user_topic TEXT NOT NULL DEFAULT '',working_summary TEXT NOT NULL DEFAULT '',updated_at INTEGER NOT NULL);
INSERT INTO continuity_state(id,updated_at) VALUES(1,0);
CREATE TABLE notifications(id INTEGER PRIMARY KEY,description TEXT NOT NULL,priority REAL NOT NULL,status TEXT NOT NULL DEFAULT 'pending',source_event_id INTEGER REFERENCES events(id),created_at INTEGER NOT NULL);
CREATE TABLE initiatives(id INTEGER PRIMARY KEY,reason TEXT NOT NULL,expected_value REAL NOT NULL,urgency REAL NOT NULL,interruption_cost REAL NOT NULL,confidence REAL NOT NULL,risk TEXT NOT NULL,expiry INTEGER,decision TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued',project_id INTEGER REFERENCES projects(id),created_at INTEGER NOT NULL);
CREATE TABLE internal_state(id INTEGER PRIMARY KEY CHECK(id=1),confidence REAL NOT NULL DEFAULT 0.5,curiosity REAL NOT NULL DEFAULT 0.2,engagement REAL NOT NULL DEFAULT 0.5,frustration REAL NOT NULL DEFAULT 0,cognitive_load REAL NOT NULL DEFAULT 0,satisfaction REAL NOT NULL DEFAULT 0.5,drives_json TEXT NOT NULL DEFAULT '{}',updated_at INTEGER NOT NULL);
INSERT INTO internal_state(id,updated_at) VALUES(1,0);
CREATE TABLE retrieval_diagnostics(id INTEGER PRIMARY KEY,query TEXT NOT NULL,depth TEXT NOT NULL,kind TEXT NOT NULL,results_json TEXT NOT NULL,created_at INTEGER NOT NULL);

CREATE VIRTUAL TABLE episodes_fts USING fts5(title,summary,content,content='episodes',content_rowid='id',tokenize='unicode61');
CREATE VIRTUAL TABLE journal_fts USING fts5(narrative,summary,content='journal_entries',content_rowid='id',tokenize='unicode61');
CREATE VIRTUAL TABLE facts_fts USING fts5(subject,predicate,object,content='facts',content_rowid='id',tokenize='unicode61');
CREATE VIRTUAL TABLE praxis_fts USING fts5(name,trigger,procedure,rationale,content='praxis',content_rowid='id',tokenize='unicode61');
CREATE VIRTUAL TABLE artifacts_fts USING fts5(path,description,content='artifacts',content_rowid='id',tokenize='unicode61');
CREATE TRIGGER episodes_insert AFTER INSERT ON episodes BEGIN INSERT INTO episodes_fts(rowid,title,summary,content) VALUES(new.id,new.title,new.summary,new.content); END;
CREATE TRIGGER episodes_update AFTER UPDATE OF title,summary,content ON episodes BEGIN INSERT INTO episodes_fts(episodes_fts,rowid,title,summary,content) VALUES('delete',old.id,old.title,old.summary,old.content); INSERT INTO episodes_fts(rowid,title,summary,content) VALUES(new.id,new.title,new.summary,new.content); END;
CREATE TRIGGER journal_insert AFTER INSERT ON journal_entries BEGIN INSERT INTO journal_fts(rowid,narrative,summary) VALUES(new.id,new.narrative,new.summary); END;
CREATE TRIGGER journal_update AFTER UPDATE OF narrative,summary ON journal_entries BEGIN INSERT INTO journal_fts(journal_fts,rowid,narrative,summary) VALUES('delete',old.id,old.narrative,old.summary); INSERT INTO journal_fts(rowid,narrative,summary) VALUES(new.id,new.narrative,new.summary); END;
CREATE TRIGGER facts_insert AFTER INSERT ON facts BEGIN INSERT INTO facts_fts(rowid,subject,predicate,object) VALUES(new.id,new.subject,new.predicate,new.object); END;
CREATE TRIGGER facts_update AFTER UPDATE OF subject,predicate,object ON facts BEGIN INSERT INTO facts_fts(facts_fts,rowid,subject,predicate,object) VALUES('delete',old.id,old.subject,old.predicate,old.object); INSERT INTO facts_fts(rowid,subject,predicate,object) VALUES(new.id,new.subject,new.predicate,new.object); END;
CREATE TRIGGER praxis_insert AFTER INSERT ON praxis BEGIN INSERT INTO praxis_fts(rowid,name,trigger,procedure,rationale) VALUES(new.id,new.name,new.trigger,new.procedure,new.rationale); END;
CREATE TRIGGER praxis_update AFTER UPDATE OF name,trigger,procedure,rationale ON praxis BEGIN INSERT INTO praxis_fts(praxis_fts,rowid,name,trigger,procedure,rationale) VALUES('delete',old.id,old.name,old.trigger,old.procedure,old.rationale); INSERT INTO praxis_fts(rowid,name,trigger,procedure,rationale) VALUES(new.id,new.name,new.trigger,new.procedure,new.rationale); END;
CREATE TRIGGER artifacts_insert AFTER INSERT ON artifacts BEGIN INSERT INTO artifacts_fts(rowid,path,description) VALUES(new.id,new.path,new.description); END;
CREATE TRIGGER artifacts_update AFTER UPDATE OF path,description ON artifacts BEGIN INSERT INTO artifacts_fts(artifacts_fts,rowid,path,description) VALUES('delete',old.id,old.path,old.description); INSERT INTO artifacts_fts(rowid,path,description) VALUES(new.id,new.path,new.description); END;
